# A tiny rule-based chatbot
print("Bot: Hi! Ask me about timings, fees or library. Type bye to stop.")
while True:
    msg = input("You: ").lower()
    if "bye" in msg:
        print("Bot: Bye! Have a good day.")
        break
    elif "timing" in msg or "time" in msg:
        print("Bot: School runs from 8 am to 2 pm.")
    elif "fee" in msg:
        print("Bot: Please ask the school office for fee details.")
    elif "library" in msg:
        print("Bot: The library is open from 9 am to 1 pm.")
    else:
        print("Bot: Sorry, I do not know that yet.")

