formula.en:
# Spam checker: counts suspicious words
spam_words = ["lottery", "winner", "free", "urgent", "otp", "click"]
messages = [
    "Congratulations winner! Click to claim your free lottery prize",
    "Class test moved to Friday",
    "Urgent: share OTP to stop your account block",
]
for m in messages:
    words = m.lower().replace(":", "").replace("!", "").split()
    score = 0
    for w in words:
        if w in spam_words:
            score = score + 1
    if score >= 2:
        label = "SPAM"
    else:
        label = "OK"
    print(label, score, "-", m)

